import assert from 'node:assert/strict';
import test from 'node:test';
import { DatabaseSync } from 'node:sqlite';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { readDevinDesktopApiKey } from '../src/desktop-auth.ts';

test('does not resurrect a logged-out Desktop token from freed SQLite pages', async (t) => {
  const dir = mkdtempSync(join(tmpdir(), 'devin-desktop-test-'));
  const path = join(dir, 'state.vscdb'); const previous = process.env.DEVIN_DESKTOP_STATE_DB;
  process.env.DEVIN_DESKTOP_STATE_DB = path;
  t.after(() => { if (previous === undefined) delete process.env.DEVIN_DESKTOP_STATE_DB; else process.env.DEVIN_DESKTOP_STATE_DB = previous; rmSync(dir, {recursive:true, force:true}); });
  const db = new DatabaseSync(path);
  db.exec('PRAGMA secure_delete=OFF; CREATE TABLE ItemTable (key TEXT PRIMARY KEY, value TEXT)');
  const key = 'synthetic-desktop-token-for-test';
  db.prepare('INSERT INTO ItemTable VALUES (?, ?)').run('windsurfAuthStatus', JSON.stringify({apiKey:key}));
  assert.equal((await readDevinDesktopApiKey()).apiKey, key);
  db.prepare('DELETE FROM ItemTable WHERE key=?').run('windsurfAuthStatus');
  db.close();
  assert.equal(await readDevinDesktopApiKey(), null);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import fs from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { syncBuiltinESMExports } from 'node:module';
import { authStatus } from '../src/credentials.ts';
import { clearDevinBinCache } from '../src/cli.ts';

test('an existing credential file cannot turn CLI Not logged in into a successful status', async (t) => {
  const dir = fs.mkdtempSync(join(tmpdir(), 'devin-auth-test-'));
  const script = join(dir, 'status.cjs');
  fs.writeFileSync(script, 'console.log("Not logged in");');
  const cli = join(dir, process.platform === 'win32' ? 'devin.cmd' : 'devin');
  fs.writeFileSync(cli, process.platform === 'win32' ? `@echo off\r\n"${process.execPath}" "${script}"\r\n` : `#!/bin/sh\nexec "${process.execPath}" "${script}"\n`, {mode: 0o700});
  const previous = process.env.DEVIN_CLI;
  process.env.DEVIN_CLI = cli; clearDevinBinCache();
  const read = fs.readFileSync, exists = fs.existsSync;
  const isCredentials = (path) => String(path).replaceAll('\\', '/').endsWith('devin/credentials.toml');
  t.mock.method(fs, 'readFileSync', (path, ...args) => isCredentials(path) ? 'api_key = "synthetic-test-key"\n' : read(path, ...args));
  t.mock.method(fs, 'existsSync', (path) => isCredentials(path) || exists(path));
  syncBuiltinESMExports();
  t.after(() => { t.mock.restoreAll(); syncBuiltinESMExports(); if (previous === undefined) delete process.env.DEVIN_CLI; else process.env.DEVIN_CLI = previous; clearDevinBinCache(); fs.rmSync(dir, {recursive:true, force:true}); });
  const status = await authStatus();
  assert.equal(status.loggedIn, false);
  assert.equal(status.summary, 'Not logged in');
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { modelsFromCatalog, resolveModelUid } from '../src/models.ts';
const family = (variants) => ({ families: [{ family_label: 'Test', family_uid: 'test', slug: 'test.family', variants }] });

test('parses current CLI prices without inventing cache rates', () => {
  const [m] = modelsFromCatalog(family([{ model_uid: 'test-high', label: 'Test High', cost_summary: '$10 / 1M Input · $0.25 / 1M Cached input · $50 / 1M Output' }]));
  assert.deepEqual(m.cost, { input: 10, output: 50, cacheRead: 0.25, cacheWrite: 0 });
  const [old] = modelsFromCatalog(family([{ model_uid: 'test', label: 'Test', cost_summary: '$2/MTok In, $8/MTok Out' }]));
  assert.deepEqual(old.cost, { input: 2, output: 8, cacheRead: 0, cacheWrite: 0 });
});

test('keeps the family ID and resolves a single non-thinking variant', () => {
  const [m] = modelsFromCatalog(family([{ model_uid: 'MODEL_PRIVATE_11', label: 'Test' }]));
  assert.equal(m.id, 'test.family'); assert.equal(m.reasoning, false);
  assert.equal(resolveModelUid(m.id, m.thinkingLevelMap), 'MODEL_PRIVATE_11');
  assert.equal(m.thinkingLevelMap.high, null);
});

test('maps uppercase IDs and private IDs using CLI effort labels', () => {
  const [m] = modelsFromCatalog(family([
    { model_uid: 'MODEL_GEMINI_MINIMAL', label: 'Test Minimal' },
    { model_uid: 'MODEL_PRIVATE_13', label: 'Test Low Thinking' },
    { model_uid: 'MODEL_PRIVATE_12', label: 'Test No Thinking' },
    { model_uid: 'MODEL_PRIVATE_15', label: 'Test High Thinking' },
  ]));
  assert.equal(m.thinkingLevelMap.minimal, 'MODEL_GEMINI_MINIMAL');
  assert.equal(m.thinkingLevelMap.low, 'MODEL_PRIVATE_13');
  assert.equal(m.thinkingLevelMap.off, 'MODEL_PRIVATE_12');
  assert.equal(m.thinkingLevelMap.high, 'MODEL_PRIVATE_15');
  assert.equal(m.thinkingLevelMap.medium, null);
});

test('uses the CLI label for the unsuffixed SWE max variant and excludes premium variants', () => {
  const [m] = modelsFromCatalog(family([
    { model_uid: 'swe-1-7', label: 'SWE-1.7 Max' },
    { model_uid: 'swe-1-7-medium', label: 'SWE-1.7 Medium' },
    { model_uid: 'swe-1-7-high-fast', label: 'SWE-1.7 High Fast' },
  ]));
  assert.equal(m.thinkingLevelMap.max, 'swe-1-7');
  assert.equal(m.thinkingLevelMap.high, null);
});

test('does not advertise a hardcoded cloud catalog when offline or empty', () => {
  assert.deepEqual(modelsFromCatalog(null), []);
  assert.deepEqual(modelsFromCatalog({families: []}), []);
});

