import assert from "node:assert/strict";
import { mkdtempSync, rmSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import {
  catalogCachePath,
  isUsableCatalog,
  isCatalogCacheFresh,
  readCatalogCache,
  writeCatalogCache,
} from "../src/catalog-cache.ts";

const catalog = {
  families: [{
    family_label: "SWE-2",
    family_uid: "swe-2",
    slug: "swe-2",
    variants: [{ model_uid: "swe-2-high", label: "SWE-2 High" }],
  }],
};

test("writes and reads a validated catalog atomically", (t) => {
  const directory = mkdtempSync(join(tmpdir(), "pi-devin-cache-"));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  const path = join(directory, "nested", "models.json");
  writeCatalogCache(catalog, path, 1_000);
  assert.deepEqual(readCatalogCache(path), { catalog, fetchedAt: 1_000 });
  assert.equal(JSON.parse(readFileSync(path, "utf8")).version, 1);
});

test("rejects malformed cache content", (t) => {
  const directory = mkdtempSync(join(tmpdir(), "pi-devin-cache-"));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  const path = join(directory, "models.json");
  writeFileSync(path, JSON.stringify({ version: 1, fetchedAt: 1_000, catalog: { families: [{}] } }));
  assert.throws(() => readCatalogCache(path), /Invalid Devin model catalog cache/);
});

test("rejects catalogs without usable model families", () => {
  assert.equal(isUsableCatalog({ families: [] }), false);
  assert.equal(isUsableCatalog({
    families: [{ family_label: "Empty", family_uid: "empty", slug: "empty", variants: [] }],
  }), false);
});

test("checks cache age and future timestamps", () => {
  const cached = { catalog, fetchedAt: 1_000 };
  assert.equal(isCatalogCacheFresh(cached, 1_500, 500), true);
  assert.equal(isCatalogCacheFresh(cached, 1_501, 500), false);
  assert.equal(isCatalogCacheFresh(cached, 999, 500), false);
});

test("uses XDG cache directory when configured", () => {
  assert.equal(catalogCachePath({ XDG_CACHE_HOME: "/cache" }, "/home/test"), join("/cache", "pi-devin", "models.json"));
  assert.equal(catalogCachePath({}, "/home/test"), join("/home/test", ".cache", "pi-devin", "models.json"));
});

for (const [field, value] of Object.entries({ cost_summary: {}, max_context_tokens: "1000", max_output_tokens: -1, model_uid: "", is_beta: "yes" })) {
  test(`rejects invalid ${field} before model conversion`, () => {
    const malformed = structuredClone(catalog);
    malformed.families[0].variants[0][field] = value;
    assert.equal(isUsableCatalog(malformed), false);
  });
}

import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { runDevin } from "./cli.js";
import { readDevinDesktopApiKey } from "./desktop-auth.js";

export interface DevinCredentials {
  apiKey: string;
  apiServerUrl: string;
  webappHost: string;
  apiUrl: string;
  path: string;
}

const CREDENTIALS_PATH = join(homedir(), ".local/share/devin/credentials.toml");

function parseTomlStrings(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of text.split("\n")) {
    const match = line.match(/^\s*([A-Za-z0-9_]+)\s*=\s*"(.*)"\s*$/);
    if (match) out[match[1]] = match[2];
  }
  return out;
}

export function credentialsPath(): string {
  return CREDENTIALS_PATH;
}

export function writeCredentials(apiKey: string): DevinCredentials {
  const body = [
    `windsurf_api_key = ${JSON.stringify(apiKey)}`,
    `api_server_url = "https://server.codeium.com"`,
    `devin_webapp_host = "app.devin.ai"`,
    `devin_api_url = "https://api.devin.ai"`,
    "",
  ].join("\n");
  mkdirSync(dirname(CREDENTIALS_PATH), { recursive: true });
  writeFileSync(CREDENTIALS_PATH, body, { mode: 0o600 });
  try {
    chmodSync(CREDENTIALS_PATH, 0o600);
  } catch {
    // best effort on platforms without POSIX modes
  }
  const creds = readCredentials();
  if (!creds) throw new Error(`Wrote ${CREDENTIALS_PATH} but could not read it back.`);
  return creds;
}

/**
 * Seed the CLI store from a signed-in Devin Desktop.
 * Only fills the gap: an existing CLI store is never overwritten.
 */
export async function importFromDevinDesktop(): Promise<DevinCredentials | null> {
  if (existsSync(CREDENTIALS_PATH)) return null;
  const desktop = await readDevinDesktopApiKey();
  if (!desktop) return null;
  return writeCredentials(desktop.apiKey);
}

/** CLI store first, Devin Desktop second. */
export async function ensureCredentials(): Promise<DevinCredentials | null> {
  return readCredentials() ?? (await importFromDevinDesktop());
}

export function readCredentials(): DevinCredentials | null {
  if (!existsSync(CREDENTIALS_PATH)) return null;
  const raw = parseTomlStrings(readFileSync(CREDENTIALS_PATH, "utf8"));
  const apiKey = raw.windsurf_api_key || raw.api_key;
  if (!apiKey) return null;
  return {
    apiKey,
    apiServerUrl: (raw.api_server_url || "https://server.codeium.com").replace(/\/$/, ""),
    webappHost: raw.devin_webapp_host || "app.devin.ai",
    apiUrl: raw.devin_api_url || "https://api.devin.ai",
    path: CREDENTIALS_PATH,
  };
}

export async function authStatus(): Promise<{
  loggedIn: boolean;
  summary: string;
}> {
  const creds = readCredentials();
  try {
    const { stdout, stderr, code } = await runDevin(["auth", "status"], { timeoutMs: 15_000 });
    const text = `${stdout}\n${stderr}`.trim();
    const loggedIn = code === 0 && /\blogged in\b/i.test(text) && !/\bnot logged in\b/i.test(text);
    return { loggedIn, summary: text || (creds ? "credentials.toml present" : "not signed in") };
  } catch (error) {
    if (creds) {
      return { loggedIn: true, summary: `Devin credentials present at ${CREDENTIALS_PATH}` };
    }
    return {
      loggedIn: false,
      summary: error instanceof Error ? error.message : String(error),
    };
  }
}

export async function loginWithCli(): Promise<DevinCredentials> {
  const already = readCredentials();
  const status = await authStatus();
  if (already && status.loggedIn) return already;

  // A signed-in Devin Desktop already holds a usable session token. Reuse it
  // instead of sending the user through a browser round-trip for nothing.
  const imported = await importFromDevinDesktop();
  if (imported) return imported;

  const { code } = await runDevin(["auth", "login"], { inheritStdio: true });
  const creds = readCredentials();
  if (!creds) {
    throw new Error(
      `\`devin auth login\` ${code === 0 ? "finished" : `exited ${code}`} but ${CREDENTIALS_PATH} is missing. Run \`devin auth login\` yourself, then /login devin again.`,
    );
  }
  return creds;
}

import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

/**
 * Devin Desktop (the Windsurf-based editor) keeps its sign-in in the Electron
 * state database, not in the CLI store (`~/.local/share/devin/credentials.toml`).
 * A Desktop-only sign-in therefore looks like "Not logged in" to the CLI, and
 * `/login devin` opens a browser even though the machine already holds a valid
 * session token.
 *
 * This module reads that token so the CLI store can be seeded from it.
 * It is strictly read-only: nothing here writes to Devin Desktop's data.
 */

const AUTH_KEY = "windsurfAuthStatus";

export interface DesktopCredential {
  apiKey: string;
  source: string;
}

/** Devin Desktop state databases, most specific first. */
export function desktopStateDbPaths(): string[] {
  const override = process.env.DEVIN_DESKTOP_STATE_DB;
  if (override) return [override];
  const home = homedir();
  const fallback =
    process.platform === "darwin"
      ? join(home, "Library/Application Support/Devin/User/globalStorage/state.vscdb")
      : process.platform === "win32"
        ? join(
            process.env.APPDATA ?? join(home, "AppData/Roaming"),
            "Devin/User/globalStorage/state.vscdb",
          )
        : join(home, ".config/Devin/User/globalStorage/state.vscdb");
  return [fallback];
}

function normalizeApiKey(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const apiKey = value.trim();
  // Real keys look like `devin-session-token$…` / `wspkce$…`; never contain spaces.
  if (apiKey.length < 16 || /\s/.test(apiKey)) return null;
  return apiKey;
}

function apiKeyFromStatusValue(value: unknown): string | null {
  if (typeof value !== "string" || !value.trim()) return null;
  try {
    const parsed = JSON.parse(value) as { apiKey?: unknown };
    return normalizeApiKey(parsed?.apiKey);
  } catch {
    return null;
  }
}

interface SqliteDatabase {
  prepare(sql: string): { get(...params: unknown[]): unknown };
  close(): void;
}

interface SqliteModule {
  DatabaseSync: new (path: string, options?: { readOnly?: boolean }) => SqliteDatabase;
}

/**
 * Preferred path: `node:sqlite` (Node 22.5+) reads the row properly, so stale
 * copies left behind by earlier writes can never win.
 */
async function apiKeyFromSqlite(dbPath: string): Promise<string | null> {
  try {
    const sqlite = (await import("node:sqlite")) as unknown as SqliteModule;
    const db = new sqlite.DatabaseSync(dbPath, { readOnly: true });
    try {
      const row = db.prepare("SELECT value FROM ItemTable WHERE key = ?").get(AUTH_KEY) as
        | { value?: unknown }
        | undefined;
      return apiKeyFromStatusValue(row?.value);
    } finally {
      db.close();
    }
  } catch {
    return null;
  }
}

/** Session token of a signed-in Devin Desktop, or null when there is none. */
export async function readDevinDesktopApiKey(): Promise<DesktopCredential | null> {
  for (const dbPath of desktopStateDbPaths()) {
    if (!existsSync(dbPath)) continue;
    const apiKey = await apiKeyFromSqlite(dbPath);
    if (apiKey) return { apiKey, source: dbPath };
  }
  return null;
}

import type { ThinkingLevelMap } from "@earendil-works/pi-ai";
import type { ProviderModelConfig } from "@earendil-works/pi-coding-agent";
import { runDevin } from "./cli.js";

export interface DevinVariant {
  model_uid: string;
  label: string;
  max_context_tokens?: number;
  max_output_tokens?: number;
  cost_tier?: string;
  cost_summary?: string;
  is_new?: boolean;
  is_beta?: boolean;
}

export interface DevinFamily {
  family_label: string;
  family_uid: string;
  slug: string;
  aliases?: string[];
  variants: DevinVariant[];
}

export interface DevinCatalog {
  families: DevinFamily[];
}

const THINKING_ORDER = ["off", "minimal", "low", "medium", "high", "xhigh", "max"] as const;

function parseCost(summary?: string): ProviderModelConfig["cost"] {
  const rates = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 };
  if (!summary) return rates;
  // CLI releases use both "$5/MTok In" and "$5 / 1M Input".
  for (const match of summary.matchAll(/\$([0-9]+(?:\.[0-9]+)?)\s*\/\s*(?:MTok|1M)\s+(Cached input|Cache read|Cache write|Cache creation|Input|Output|In|Out)\b/gi)) {
    const kind = match[2].toLowerCase();
    const key = kind.startsWith("cached") || kind === "cache read" ? "cacheRead"
      : kind.startsWith("cache") ? "cacheWrite" : kind.startsWith("out") ? "output" : "input";
    rates[key] = Number(match[1]);
  }
  // Do not invent provider-specific cache multipliers when the CLI omits them.
  return rates;
}

function variantKey(uid: string): string | null {
  uid = uid.toLowerCase().replaceAll("_", "-");
  const suffixes = [
    "none-priority",
    "low-priority",
    "medium-priority",
    "high-priority",
    "xhigh-priority",
    "max-priority",
    "low-fast",
    "medium-fast",
    "high-fast",
    "xhigh-fast",
    "max-fast",
    "thinking-1m",
    "thinking",
    "none",
    "low",
    "medium",
    "high",
    "xhigh",
    "max",
    "minimal",
  ];
  for (const suffix of suffixes) {
    if (uid === suffix || uid.endsWith(`-${suffix}`)) return suffix;
  }
  return null;
}

function thinkingFromSuffix(suffix: string | null): keyof ThinkingLevelMap | null {
  if (!suffix) return null;
  if (suffix === "none" || suffix === "none-priority") return "off";
  if (suffix === "minimal") return "minimal";
  if (suffix.startsWith("low")) return "low";
  if (suffix.startsWith("medium")) return "medium";
  if (suffix.startsWith("high") && !suffix.startsWith("xhigh")) return "high";
  if (suffix.startsWith("xhigh")) return "xhigh";
  if (suffix.startsWith("max")) return "max";
  if (suffix.includes("thinking")) return "high";
  return null;
}

function preferredDefault(map: ThinkingLevelMap): string | undefined {
  for (const level of ["high", "medium", "max", "xhigh", "low", "minimal", "off"] as const) {
    const value = map[level];
    if (typeof value === "string") return value;
  }
  return undefined;
}

function familyToModels(family: DevinFamily): ProviderModelConfig[] {
  const usable = family.variants.filter((variant) => {
    const key = variantKey(variant.model_uid);
    return !key || (!key.includes("priority") && !key.includes("fast") && key !== "thinking-1m");
  });
  const source = usable.length > 0 ? usable : family.variants;
  const thinkingLevelMap: ThinkingLevelMap = {};
  for (const variant of source) {
    // Legacy MODEL_PRIVATE_* IDs carry no effort; use the CLI label too.
    const labelLevel = variant.label.match(/\b(none|off|minimal|low|medium|high|x-?high|max)\b(?:\s+(?:thinking|fast))?$/i)?.[1]?.toLowerCase().replace("x-high", "xhigh");
    const level = thinkingFromSuffix(labelLevel === "off" ? "none" : labelLevel ?? variantKey(variant.model_uid))
      ?? (/no thinking/i.test(variant.label) ? "off" : /thinking/i.test(variant.label) ? "high" : "off");
    if (level && thinkingLevelMap[level] === undefined) {
      thinkingLevelMap[level] = variant.model_uid;
    }
  }
  // pi treats a missing level as supported and only null hides it, so mark every
  // level this family does not ship. The picker then matches the real variants
  // instead of silently falling back to the default one.
  for (const level of THINKING_ORDER) {
    if (thinkingLevelMap[level] === undefined) thinkingLevelMap[level] = null;
  }

  const defaultUid = preferredDefault(thinkingLevelMap) ?? source[0]?.model_uid ?? family.family_uid;
  const sample = source.find((variant) => variant.model_uid === defaultUid) ?? source[0];
  if (!sample) return [];

  const mappedLevels = THINKING_ORDER.filter((level) => typeof thinkingLevelMap[level] === "string");
  const reasoning = mappedLevels.some((level) => level !== "off");

  // With a thinking map the pi-facing id never reaches the wire — resolveModelUid
  // always maps it — so keep the family id and let pi's thinking level choose the
  // variant, instead of baking "-high" into the model id.
  const familyId = family.slug || family.family_uid || defaultUid;

  return [
    {
      id: familyId,
      name: family.family_label || family.slug || defaultUid,
      reasoning,
      thinkingLevelMap,
      input: ["text", "image"],
      cost: parseCost(sample.cost_summary),
      contextWindow: sample.max_context_tokens ?? 256_000,
      maxTokens: sample.max_output_tokens ?? 128_000,
    },
  ];
}

// Only advertise models from a successfully loaded CLI catalog or its cache.
export const FALLBACK_MODELS: ProviderModelConfig[] = [];

export function modelsFromCatalog(catalog: DevinCatalog | null): ProviderModelConfig[] {
  return catalog?.families?.flatMap(familyToModels) ?? [];
}

export async function loadCliCatalog(): Promise<DevinCatalog | null> {
  const { stdout, code, stderr } = await runDevin(["models", "list", "--format", "json"], {
    timeoutMs: 20_000,
  });
  if (code !== 0) {
    throw new Error(stderr.trim() || `devin models list exited ${code}`);
  }
  const parsed = JSON.parse(stdout) as DevinCatalog;
  if (!parsed?.families) return null;
  return parsed;
}

export function resolveModelUid(
  modelId: string,
  thinkingLevelMap: ThinkingLevelMap | undefined,
  reasoning?: string,
): string {
  if (reasoning && thinkingLevelMap) {
    const mapped = thinkingLevelMap[reasoning as keyof ThinkingLevelMap];
    if (typeof mapped === "string") return mapped;
  }
  if (thinkingLevelMap) {
    const fallback = preferredDefault(thinkingLevelMap);
    if (fallback) return fallback;
  }
  return modelId;
}

import { existsSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import { randomUUID } from "node:crypto";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import type { DevinCatalog } from "./models.js";

const CACHE_VERSION = 1;

export const CATALOG_CACHE_MAX_AGE_MS = 6 * 60 * 60 * 1000;

export interface CachedDevinCatalog {
  catalog: DevinCatalog;
  fetchedAt: number;
}

interface CatalogCacheFile extends CachedDevinCatalog {
  version: typeof CACHE_VERSION;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function optionalString(value: unknown): boolean {
  return value === undefined || typeof value === "string";
}

function optionalTokenLimit(value: unknown): boolean {
  return value === undefined || (typeof value === "number" && Number.isSafeInteger(value) && value > 0);
}

export function isUsableCatalog(value: unknown): value is DevinCatalog {
  if (!isRecord(value) || !Array.isArray(value.families) || value.families.length === 0) return false;
  return value.families.some((family) => isRecord(family) && Array.isArray(family.variants) && family.variants.length > 0)
    && value.families.every((family) =>
    isRecord(family)
    && typeof family.family_label === "string"
    && typeof family.family_uid === "string"
    && typeof family.slug === "string"
    && (family.aliases === undefined || (Array.isArray(family.aliases) && family.aliases.every((alias) => typeof alias === "string")))
    && Array.isArray(family.variants)
    && family.variants.every((variant) =>
      isRecord(variant)
      && typeof variant.model_uid === "string"
      && variant.model_uid.trim().length > 0
      && typeof variant.label === "string"
      && optionalString(variant.cost_summary)
      && optionalString(variant.cost_tier)
      && optionalTokenLimit(variant.max_context_tokens)
      && optionalTokenLimit(variant.max_output_tokens)
      && (variant.is_new === undefined || typeof variant.is_new === "boolean")
      && (variant.is_beta === undefined || typeof variant.is_beta === "boolean")
    )
  );
}

export function catalogCachePath(
  env: NodeJS.ProcessEnv = process.env,
  home: string = homedir(),
): string {
  const cacheRoot = env.XDG_CACHE_HOME || join(home, ".cache");
  return join(cacheRoot, "pi-devin", "models.json");
}

export function readCatalogCache(path: string = catalogCachePath()): CachedDevinCatalog | null {
  if (!existsSync(path)) return null;
  const parsed: unknown = JSON.parse(readFileSync(path, "utf8"));
  if (
    !isRecord(parsed)
    || parsed.version !== CACHE_VERSION
    || typeof parsed.fetchedAt !== "number"
    || !Number.isFinite(parsed.fetchedAt)
    || !isUsableCatalog(parsed.catalog)
  ) {
    throw new Error(`Invalid Devin model catalog cache: ${path}`);
  }
  return { catalog: parsed.catalog, fetchedAt: parsed.fetchedAt };
}

export function writeCatalogCache(
  catalog: DevinCatalog,
  path: string = catalogCachePath(),
  fetchedAt: number = Date.now(),
): void {
  if (!isUsableCatalog(catalog)) throw new Error("Refusing to cache an invalid Devin model catalog");
  mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
  const temporaryPath = `${path}.${randomUUID()}.tmp`;
  const body: CatalogCacheFile = { version: CACHE_VERSION, fetchedAt, catalog };
  try {
    writeFileSync(temporaryPath, `${JSON.stringify(body)}\n`, { mode: 0o600 });
    renameSync(temporaryPath, path);
  } finally {
    if (existsSync(temporaryPath)) unlinkSync(temporaryPath);
  }
}

export function isCatalogCacheFresh(
  cached: CachedDevinCatalog,
  now: number = Date.now(),
  maxAgeMs: number = CATALOG_CACHE_MAX_AGE_MS,
): boolean {
  const age = now - cached.fetchedAt;
  return age >= 0 && age <= maxAgeMs;
}

